window.kbPageData["views/entry/k-6511376d3008b0bb"] = {"key":"entry/k-6511376d3008b0bb","state":{"route":"entry/k-6511376d3008b0bb"},"node":{"id":"k-6511376d3008b0bb","mode":"k","title":"货币的价值尺度职能","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":["商品经济理论 · 货币的含义和职能"],"qs":["国考 2025 行政执法 行测#3"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"主类":["概念与词义"],"出处性质":["理论手册"],"学科":["经济"],"来源主题":["马克思主义政治经济学"],"资料类别":["非时政"]},"seeAlso":["k-0683d6084713fb30","k-38158b700f6fd045","k-a50017dbab397802","k-acbbdf39b29c19f4"],"supplement":[{"doc":"3ccc56f4000d1642c2d1","file":"政治理论必学手册.pdf","first":9,"last":9,"relation":"辨析","evidenceId":"bb96843a5abd31e5511d","cardId":"db4a7e019f79c6eb","questionId":null,"basis":"理论手册","quote":"2.职能：价值尺度（不需要现实的货币，只需要观念上的货币，常见形式为标价）、流通手段（币充当商品交换的媒介）、支付手段（赊购赊销）、贮藏手段（必须是足值的金属货币或金属条块）、世界货币。","text":"商店给商品标价时，货币用于表现价值，不要求当场付钱。","reference":null}],"directorySummary":"价值尺度是货币以自身价值为尺度衡量其他商品价值的职能。商品的价值用货币表现出来就是价格。","review":{"definition":"价值尺度是货币以自身价值为尺度衡量其他商品价值的职能。商品的价值用货币表现出来就是价格。","explanation":"给商品标价时，使用观念上的货币即可衡量商品价值。第3题B项把实际的物质交换说成发挥价值尺度职能的条件，因而错误。","references":[],"evidence":"只需要观念上的货币，不需要通过实际的物质交换来实现。","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"db4a7e019f79c6eb","label":"商品经济理论 · 货币的含义和职能","topic":"马克思主义政治经济学","category":"非时政","text":"五、货币的含义和职能\n1.含义：货币是在长期交换过程中形成的固定地充当一般等价物的特殊商品。\n2.职能：价值尺度（不需要现实的货币，只需要观念上的货币，常见形式为标价）、流\n通手段（币充当商品交换的媒介）、支付手段（赊购赊销）、贮藏手段（必须是足值的金属货\n币或金属条块）、世界货币。其中价值尺度和流通手段是货币的两种最基本职能。\n（粉笔敲黑板：区分并记忆货币的五大职能，考试中给相关案例需要区分出体现的是货\n币的哪个职能）","source":{"doc":"3ccc56f4000d1642c2d1","first":9,"last":9,"page":9,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{"国考 2025 行政执法 行测#3":{"paper":"国考 2025 行政执法 行测","n":3,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",1],"asrc":["e2c4b1970d2b49eac0fd.pdf",1],"card":"336f02923851603a0b694fe9","links":[{"id":"k-6511376d3008b0bb","role":"解题依据","why":"判别价值尺度的实现条件，需要知道货币以观念形式即可衡量商品价值。"}]}},"terms":{"k-0683d6084713fb30":{"id":"k-0683d6084713fb30","mode":"k","type":"概念与词义","title":"货币的流通手段职能","qs":[],"count":0},"k-38158b700f6fd045":{"id":"k-38158b700f6fd045","mode":"k","type":"概念与词义","title":"货币的支付手段职能","qs":[],"count":0},"k-a50017dbab397802":{"id":"k-a50017dbab397802","mode":"k","type":"概念与词义","title":"世界货币","qs":[],"count":0},"k-acbbdf39b29c19f4":{"id":"k-acbbdf39b29c19f4","mode":"k","type":"概念与词义","title":"货币的贮藏手段职能","qs":[],"count":0}},"references":{},"topics":[],"units":{"k-6511376d3008b0bb":[["国考 2025 行政执法 行测#3"]]}};
